package app.still.planner;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.media.*;import android.content.pm.PackageManager;import org.json.*;
/** System countdown and completion alert, independent of WebView foreground lifetime. */
public final class TimerAlerts extends BroadcastReceiver {
 static final int LIVE=91001,DONE=91002,ALARM=91003,IMMUTABLE=0x04000000;
 static final String RUNNING="still_timer_running",FINISHED="still_timer_finished_v1";
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("timer_alerts",0);}
 static Uri sound(Context c){return Uri.parse("android.resource://"+c.getPackageName()+"/"+R.raw.timer_chime);}
 static boolean notificationsAllowed(Context c){return Build.VERSION.SDK_INT<33||c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==PackageManager.PERMISSION_GRANTED;}
 static void channels(Context c){if(Build.VERSION.SDK_INT<26)return;try{Class<?> cl=Class.forName("android.app.NotificationChannel");Object nm=c.getSystemService(Context.NOTIFICATION_SERVICE);Object live=cl.getConstructor(String.class,CharSequence.class,int.class).newInstance(RUNNING,"Running timer",2);cl.getMethod("setSound",Uri.class,AudioAttributes.class).invoke(live,null,null);Object done=cl.getConstructor(String.class,CharSequence.class,int.class).newInstance(FINISHED,"Timer complete",4);cl.getMethod("setSound",Uri.class,AudioAttributes.class).invoke(done,sound(c),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());cl.getMethod("enableVibration",boolean.class).invoke(done,true);nm.getClass().getMethod("createNotificationChannel",cl).invoke(nm,live);nm.getClass().getMethod("createNotificationChannel",cl).invoke(nm,done);}catch(Exception ignored){}}
 static boolean exactAllowed(Context c){if(Build.VERSION.SDK_INT<31)return true;try{return (Boolean)AlarmManager.class.getMethod("canScheduleExactAlarms").invoke(c.getSystemService(Context.ALARM_SERVICE));}catch(Exception e){return false;}}
 static PendingIntent open(Context c){return PendingIntent.getActivity(c,LIVE,new Intent(c,MainActivity.class).putExtra("action","focus"),PendingIntent.FLAG_UPDATE_CURRENT|IMMUTABLE);}
 static Notification.Builder builder(Context c,String channel)throws Exception {Notification.Builder b=new Notification.Builder(c).setSmallIcon(R.drawable.app_icon).setContentIntent(open(c)).setCategory("stopwatch").setVisibility(Notification.VISIBILITY_PUBLIC);if(Build.VERSION.SDK_INT>=26)Notification.Builder.class.getMethod("setChannelId",String.class).invoke(b,channel);return b;}
 static PendingIntent alarm(Context c,String key,String mode,long end){return PendingIntent.getBroadcast(c,ALARM,new Intent(c,TimerAlerts.class).setAction("finish").putExtra("key",key).putExtra("mode",mode).putExtra("end",end),PendingIntent.FLAG_UPDATE_CURRENT|IMMUTABLE);}
 static PendingIntent control(Context c,JSONObject t,String command){String token=TimerState.token(t);Intent i=new Intent(c,TimerAlerts.class).setAction(command).setData(Uri.parse("still://timer/"+Uri.encode(token)+"/"+command)).putExtra("token",token).addFlags(Intent.FLAG_RECEIVER_FOREGROUND);return PendingIntent.getBroadcast(c,LIVE,i,PendingIntent.FLAG_UPDATE_CURRENT|IMMUTABLE);}
 static synchronized void refresh(Context c,JSONObject root){channels(c);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);JSONObject t=root.optJSONObject("timer");long now=System.currentTimeMillis();boolean running=t!=null&&t.optBoolean("running")&&t.optLong("endAt")>now;SharedPreferences p=prefs(c);
  if(!running){am.cancel(alarm(c,"","",0));p.edit().remove("scheduled").apply();if(t==null||t.optBoolean("running")){nm.cancel(LIVE);return;}}
  long end=t.optLong("endAt");String key=t.optString("id")+"@"+end,mode=t.optString("mode"),label="focus".equals(mode)?"Focus timer":"Break timer";
  if(running&&(!key.equals(p.getString("scheduled",""))||p.getBoolean("exact",false)!=exactAllowed(c))){PendingIntent pi=alarm(c,key,mode,end);try{if(exactAllowed(c))am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,end,pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,end,pi);p.edit().putString("scheduled",key).putBoolean("exact",exactAllowed(c)).apply();}catch(SecurityException e){am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,end,pi);p.edit().putString("scheduled",key).putBoolean("exact",exactAllowed(c)).apply();}}
  if(!notificationsAllowed(c)||key.equals(p.getString("dismissed","")))return;
  try{Notification.Builder b=builder(c,RUNNING).setContentTitle(label).setContentText(running?"Time remaining":"Paused · "+TimerIslandPayload.remaining(t,now)).setWhen(end).setShowWhen(running).setUsesChronometer(running).setOngoing(true).setOnlyAlertOnce(true).setColor(android.graphics.Color.parseColor("#B89DFF"));
   b.setChronometerCountDown(true);
   Notification.Action toggle=new Notification.Action.Builder(android.graphics.drawable.Icon.createWithResource(c,running?R.drawable.timer_pause:R.drawable.timer_play),running?"Pause":"Resume",control(c,t,running?"pause":"resume")).build();
   Notification.Action stop=new Notification.Action.Builder(android.graphics.drawable.Icon.createWithResource(c,R.drawable.timer_stop),"Stop",control(c,t,"stop")).build();b.addAction(toggle).addAction(stop);
   b.setDeleteIntent(PendingIntent.getBroadcast(c,LIVE,new Intent(c,TimerAlerts.class).setAction("dismiss").putExtra("key",key),PendingIntent.FLAG_UPDATE_CURRENT|IMMUTABLE));
   if(Build.VERSION.SDK_INT>=36){Bundle extras=new Bundle();extras.putBoolean("android.requestPromotedOngoing",true);b.addExtras(extras);}
   XiaomiTimerIsland.attach(c,b,t,toggle,stop);nm.notify(LIVE,b.build());
  }catch(Exception ignored){}
 }
 static void command(final Context context,final Intent intent,final PendingResult result){final Context c=context.getApplicationContext();new Thread(new Runnable(){public void run(){Store store=new Store(c);try{boolean changed;synchronized(Store.LOCK){String raw=store.load();if(raw.isEmpty())return;JSONObject root=new JSONObject(raw);changed=TimerState.apply(root,intent.getAction(),intent.getStringExtra("token"),System.currentTimeMillis());if(changed)store.save(root.toString());}if(changed){ReminderReceiver.reschedule(c);TodayWidget.refreshAll(c);c.sendBroadcast(new Intent("app.still.planner.TIMER_CHANGED").setPackage(c.getPackageName()));}}catch(Exception e){android.util.Log.w("StillTimer","Timer control could not be saved",e);}finally{store.close();result.finish();}}},"Still timer control").start();}
 static synchronized void complete(final Context c,String key,String mode,boolean foreground){SharedPreferences p=prefs(c);if(key.equals(p.getString("delivered","")))return;p.edit().putString("delivered",key).remove("scheduled").apply();NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.cancel(LIVE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(alarm(c,"","",0));channels(c);
  if(notificationsAllowed(c)){try{Notification.Builder b=builder(c,FINISHED).setContentTitle("focus".equals(mode)?"Focus session complete":"Break complete").setContentText("Your timer has finished.").setAutoCancel(true).setCategory(Notification.CATEGORY_ALARM).setSound(sound(c)).setVibrate(new long[]{0,160,100,160});nm.notify(DONE,b.build());}catch(Exception ignored){}}
  else if(foreground){new Handler(Looper.getMainLooper()).post(new Runnable(){public void run(){try{final Ringtone r=RingtoneManager.getRingtone(c,sound(c));r.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());r.play();new Handler(Looper.getMainLooper()).postDelayed(new Runnable(){public void run(){r.stop();}},3000);}catch(Exception ignored){}}});}
 }
 public void onReceive(Context c,Intent i){if("pause".equals(i.getAction())||"resume".equals(i.getAction())||"stop".equals(i.getAction())){command(c,i,goAsync());return;}if("dismiss".equals(i.getAction())){prefs(c).edit().putString("dismissed",i.getStringExtra("key")).apply();return;}Store store=new Store(c);try{JSONObject root=new JSONObject(store.load()),t=root.optJSONObject("timer");if(t==null||!t.optBoolean("running"))return;String key=t.optString("id")+"@"+t.optLong("endAt");if(!key.equals(i.getStringExtra("key"))||t.optLong("endAt")>System.currentTimeMillis()+1000)return;complete(c,key,t.optString("mode"),false);}catch(Exception ignored){}finally{store.close();}}
}
